"""Image-derived trajectories; uses only the supplied exemplar and calibrated pen width."""
import numpy as np
from scipy import ndimage as ndi
from scipy.spatial import cKDTree
from PIL import Image,ImageDraw
from pathlib import Path

def contours(f,level):
    h,w=f.shape
    hh=(f[:,:-1]<level)!=(f[:,1:]<level)
    vv=(f[:-1,:]<level)!=(f[1:,:]<level)
    # Vertex ids are grid edges, thus adjacent squares use exactly the same id.
    H=h*(w-1)
    ys,xs=np.where(hh); vids=(ys*(w-1)+xs).tolist()
    fr=(level-f[ys,xs])/(f[ys,xs+1]-f[ys,xs])
    pos={int(i):np.array([x+a,y],float) for i,x,y,a in zip(vids,xs,ys,fr)}
    ys,xs=np.where(vv); vids=(H+ys*w+xs).tolist()
    fr=(level-f[ys,xs])/(f[ys+1,xs]-f[ys,xs])
    pos.update({int(i):np.array([x,y+a],float) for i,x,y,a in zip(vids,xs,ys,fr)})
    adj={i:[] for i in pos}
    count=hh[:-1,:].astype(int)+hh[1:,:]+vv[:,:-1]+vv[:,1:]
    for y,x in zip(*np.where(count)):
        ids=[]
        if hh[y,x]: ids.append(y*(w-1)+x)
        if vv[y,x+1]: ids.append(H+y*w+x+1)
        if hh[y+1,x]: ids.append((y+1)*(w-1)+x)
        if vv[y,x]: ids.append(H+y*w+x)
        if len(ids)==2: pairs=[ids]
        elif len(ids)==4:
            # The very rare saddle is split into two arcs.
            a,b,c,d=ids
            pairs=[(a,b),(c,d)] if ((f[y:y+2,x:x+2].mean()>=level)==(f[y,x]>=level)) else [(a,d),(b,c)]
        else: raise RuntimeError(ids)
        for a,b in pairs: adj[a].append(b); adj[b].append(a)
    loops=[]; remaining=set(pos)
    while remaining:
        start=min(remaining); cur=start; prev=None; ids=[]
        while True:
            ids.append(cur); remaining.discard(cur)
            ns=adj[cur]; nxt=ns[0] if ns[0]!=prev else ns[-1]
            prev,cur=cur,nxt
            if cur==start: break
            if len(ids)>len(pos)+1: raise RuntimeError('contour loop')
        loops.append(np.array([pos[i] for i in ids]))
    return loops

def resample(path,ds,closed=False):
    if closed: path=np.vstack([path,path[0]])
    d=np.r_[0,np.linalg.norm(np.diff(path,axis=0),axis=1).cumsum()]
    if d[-1]<1e-6: return path[:1]
    t=np.linspace(0,d[-1],max(2,int(np.ceil(d[-1]/ds))+1))
    return np.c_[np.interp(t,d,path[:,0]),np.interp(t,d,path[:,1])]

def segment_good(p,q,d,margin):
    xy=np.linspace(p,q,max(2,int(np.linalg.norm(p-q)*2)+1))
    return np.min(ndi.map_coordinates(d,[xy[:,1],xy[:,0]],order=1))>=margin

def plan_region(mask,inset=2.5,spacing=2.5):
    d=ndi.distance_transform_edt(mask)
    loops=[]; levels=[]
    for lev in np.arange(inset,d.max(),spacing):
        for p in contours(d,lev):
            if len(p)<3: continue
            loops.append(p); levels.append(lev)
    if not loops: return None
    # Join closed contour tracks with the shortest interior links.
    # Parent contours from shallower layers are always nearby.
    tree=[cKDTree(p) for p in loops]
    edges=[]
    for i in range(len(loops)):
        candidates=[]
        for j in range(i):
            if levels[j]>levels[i] or levels[j]<levels[i]-spacing-1e-4: continue
            dis,ind=tree[j].query(loops[i]); k=int(dis.argmin()); l=int(ind[k])
            candidates.append((dis[k],j,k,l))
        candidates.sort()
        for dist,j,k,l in candidates:
            if segment_good(loops[i][k],loops[j][l],d,inset-.6):
                edges.append((dist,i,j,k,l))
                # Several edges support connecting holes in the outer layer.
                if len([e for e in edges if e[1]==i])>=4: break
    # Also permit same-layer edges in either index order (already included above).
    edges.sort()
    parent=list(range(len(loops)))
    def root(i):
        while parent[i]!=i: parent[i]=parent[parent[i]]; i=parent[i]
        return i
    adj=[[] for p in loops]
    for dis,i,j,k,l in edges:
        ri,rj=root(i),root(j)
        if ri!=rj:
            parent[ri]=rj
            adj[i].append((k,j,l)); adj[j].append((l,i,k))
    groups={}
    for i in range(len(loops)): groups.setdefault(root(i),[]).append(i)
    trajectories=[]
    for members in groups.values():
        # Start in a thick interior region to contain the initial footprint.
        start=max(members,key=lambda i:levels[i])
        # Insert children when traversing the parent closed curve; each connector is retraced.
        def walk(i,k,prev=-1):
            p=loops[i]; n=len(p); children={}
            for a,j,b in adj[i]:
                if j!=prev: children.setdefault(a,[]).append((j,b))
            out=[]
            for off in range(n+1):
                at=(k+off)%n; out.append(p[at])
                if off<n:
                    for j,b in children.get(at,[]):
                        out.extend(walk(j,b,i)); out.append(p[at])
            return out
        path=np.array(walk(start,0))
        trajectories.append(path)
    return trajectories,loops,levels

