            total+=length;strokes+=1
            dr.line([tuple(a) for a in p], fill=(220,40,40),width=1)
            print(k,j,'length mm',round(length,1),'vertices',len(p))
    print('total mm',total,'strokes',strokes)
    im.save('/app/output/planned_paths.png')
